import{_ as t,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Catalog Product — Delete","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-product-delete","title":"Delete a Catalog Product","description":"GraphQL counterpart of DELETE /api/admin/catalog/products/{id}. For configurable products, variants cascade.","query":"mutation DeleteCatalogProduct($input: deleteAdminCatalogProductInput!) {\\n  deleteAdminCatalogProduct(input: $input) {\\n    adminCatalogProduct { _id }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": { \\"id\\": \\"/api/admin/catalog_products/42\\" }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminCatalogProduct\\": {\\n      \\"adminCatalogProduct\\": { \\"_id\\": 42 }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/delete.md","filePath":"api/graphql-api/admin/catalog/products/delete.md","lastUpdated":1787290888000}'),r={name:"api/graphql-api/admin/catalog/products/delete.md"};function i(n,e,l,s,c,h){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="catalog-product-—-delete" tabindex="-1">Catalog Product — Delete <a class="header-anchor" href="#catalog-product-—-delete" aria-label="Permalink to &quot;Catalog Product — Delete&quot;">​</a></h1><p>Equivalent to <a href="/api/rest-api/admin/catalog/products/delete.html"><code>DELETE /api/admin/catalog/products/{id}</code></a>.</p><p>The example uses an illustrative id. Replace it with a product that exists in your store — <a href="/api/graphql-api/admin/catalog/products.html"><code>adminCatalogProducts</code></a> lists valid ids.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>deleteAdminCatalogProduct</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID!</td><td>Yes</td><td>Resource IRI of the product, <code>/api/admin/catalog/products/&lt;id&gt;</code>.</td></tr></tbody></table><h2 id="reading-the-payload" tabindex="-1">Reading the Payload <a class="header-anchor" href="#reading-the-payload" aria-label="Permalink to &quot;Reading the Payload&quot;">​</a></h2><p>Select <strong>only <code>_id</code></strong> on the delete payload. The row is already gone by the time the response serialises, so any other field — <code>sku</code>, <code>name</code>, <code>status</code> — fails to resolve and turns the whole payload into <code>Internal server error</code> in <code>errors[]</code>, even though the delete itself succeeded. Capture whatever you need with a query before deleting.</p><h2 id="what-deletion-does" tabindex="-1">What Deletion Does <a class="header-anchor" href="#what-deletion-does" aria-label="Permalink to &quot;What Deletion Does&quot;">​</a></h2><ul><li><strong>Configurable variants cascade.</strong> Deleting the parent removes its variants; there is no separate call.</li><li><strong>Orders are unaffected.</strong> Order items keep their snapshot of the product, so historic orders still render after the product is gone.</li><li><strong>No in-order guard.</strong> A product that appears in open orders deletes without complaint, matching the admin panel. If you need referential integrity, enforce it before calling.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td><code>Product not found.</code></td><td>Unknown or already-deleted id</td></tr><tr><td><code>You do not have permission to manage products.</code></td><td>Token lacks <code>catalog.products.delete</code></td></tr></tbody></table>',13)]))}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
